import{_ as o,a0 as i,w as l,s as d,I as a,x as e,a1 as t,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 LaTeX 和 TeXstudio 排版文檔 | LCTT x X-CMD","titleTemplate":false,"description":"使用 LaTeX 和 TeXstudio 排版文檔 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 LaTeX 和 TeXstudio 排版文檔 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 LaTeX 和 TeXstudio 排版文檔 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20171025 Typeset your docs with LaTeX and TeXstudio on Fedora","title":"使用 LaTeX 和 TeXstudio 排版文檔","tag":"202102","desc":""},"relativePath":"202102/20171025 Typeset your docs with LaTeX and TeXstudio on Fedora.md","filePath":"[post].md"}'),c={name:"202102/20171025 Typeset your docs with LaTeX and TeXstudio on Fedora.md"};function u(h,s,m,g,f,b){const n=i("Link");return l(),d("div",null,[s[21]||(s[21]=a("h1",{id:"使用-latex-和-texstudio-排版文檔",tabindex:"-1"},[e("使用 LaTeX 和 TeXstudio 排版文檔 "),a("a",{class:"header-anchor",href:"#使用-latex-和-texstudio-排版文檔","aria-label":"Permalink to “使用 LaTeX 和 TeXstudio 排版文檔”"},"​")],-1)),s[22]||(s[22]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2017/07/latex-texstudio-945x400.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("LaTeX 是一個服務於高質量排版的",-1)),t(n,{href:"http://www.latex-project.org/about/"},{default:p(()=>[...s[0]||(s[0]=[e("文檔準備系統",-1)])]),_:1}),s[2]||(s[2]=e("。通常用於大量的技術和科學文檔的排版。不過，你也可以使用 LaTex 排版各種形式的文檔。教師可以編輯他們的考試和教學大綱，學生可以展示他們的論文和報告。這篇文章讓你嘗試使用 TeXstudio。TeXstudio 是一個便於編輯 LaTeX 文檔的軟件。",-1))]),s[23]||(s[23]=r(`<h3 id="啓動-texstudio" tabindex="-1">啓動 TeXstudio <a class="header-anchor" href="#啓動-texstudio" aria-label="Permalink to “啓動 TeXstudio”">​</a></h3><p>如果你使用的是 Fedora Workstation，請啓動軟件管理，然後輸入 TeXstudio 以搜索該應用程序。然後選擇安裝並添加 TeXstudio 到你的系統。你可以從軟件管理中啓動這個程序，或者像以往一樣在概覽中啓動這個軟件。</p><p>或者，如果你使用終端，請輸入 <code>texstudio</code>。如果未安裝該軟件包，系統將提示你安裝它。鍵入 <code>y</code> 開始安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ texstudio</span></span>
<span class="line"><span>bash: texstudio: command not found...</span></span>
<span class="line"><span>Install package &#39;texstudio&#39; to provide command &#39;texstudio&#39;? [N/y] y</span></span></code></pre></div><h3 id="你的第一份文檔" tabindex="-1">你的第一份文檔 <a class="header-anchor" href="#你的第一份文檔" aria-label="Permalink to “你的第一份文檔”">​</a></h3><p>LaTeX 命令通常以反斜槓 <code>\\</code> 開頭，命令參數用大括號 <code>{}</code> 括起來。首先聲明 <code>documentclass</code> 的類型。這個例子向你展示了該文檔的類是一篇文章。</p><p>然後，在聲明 <code>documentclass</code> 之後，用 <code>begin</code> 和 <code>end</code> 標記文檔的開始和結束。在這些命令之間，寫一段類似以下的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\documentclass{article}</span></span>
<span class="line"><span>\\begin{document}</span></span>
<span class="line"><span>The Fedora Project is a project sponsored by Red Hat primarily to co-ordinate the development of the Linux-based Fedora operating system, operating with the vision that the project &quot;creates a world where free culture is welcoming and widespread, collaboration is commonplace, and people control their content and devices&quot;. The Fedora Project was founded on 22 September 2003 when Red Hat decided to split Red Hat Linux into Red Hat Enterprise Linux (RHEL) and a community-based operating system, Fedora.</span></span>
<span class="line"><span>\\end{document}</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-05-20-19-15.png" alt=""></p><h3 id="使用間距" tabindex="-1">使用間距 <a class="header-anchor" href="#使用間距" aria-label="Permalink to “使用間距”">​</a></h3><p>要創建段落分隔符，請在文本之間保留一個或多個換行符。下面是一個包含四個段落的示例：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-18-14-24-42.png" alt=""></p><p>從該示例中可以看出，多個換行符不會在段落之間創建額外的空格。但是，如果你確實需要留出額外的空間，請使用 <code>hspace</code> 和 <code>vspace</code> 命令。這兩個命令分別添加水平和垂直空間。下面是一些示例代碼，顯示了段落周圍的附加間距：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\documentclass{article}</span></span>
<span class="line"><span>\\begin{document}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\hspace{2.5cm} The four essential freedoms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\vspace{0.6cm} </span></span>
<span class="line"><span>A program is free software if the program&#39;s users have the 4 essential freedoms:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The freedom to run the program as you wish, for any purpose (freedom 0).\\vspace{0.2cm} </span></span>
<span class="line"><span>The freedom to study how the program works, and change it so it does your computing as you wish (freedom 1). Access to the source code is a precondition for this.\\vspace{0.2cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The freedom to redistribute copies so you can help your neighbour (freedom 2).\\vspace{0.2cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The freedom to distribute copies of your modified versions to others (freedom 3). By doing this you can give the whole community a chance to benefit from your changes. Access to the source code is a precondition for this.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\end{document}</span></span></code></pre></div><p>如果需要，你也可以使用 <code>noindent</code> 命令來避免縮進。這裏是上面 LaTeX 源碼的結果：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-18-17-24-53.png" alt=""></p><h3 id="使用列表和格式" tabindex="-1">使用列表和格式 <a class="header-anchor" href="#使用列表和格式" aria-label="Permalink to “使用列表和格式”">​</a></h3><p>如果把自由軟件的四大基本自由列為一個清單，這個例子看起來會更好。通過在列表的開頭使用<code>\\begin{itemize}</code>，在末尾使用 <code>\\end{itemize}</code> 來設置列表結構。在每個項目前面加上 <code>\\item</code> 命令。</p><p>額外的格式也有助於使文本更具可讀性。用於格式化的有用命令包括粗體、斜體、下劃線、超大、大、小和 textsc 以幫助強調文本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\documentclass{article}</span></span>
<span class="line"><span>\\begin{document}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\hspace{2cm} {\\huge The four essential freedoms}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\vspace{0.6cm} </span></span>
<span class="line"><span>\\noindent {\\large A program is free software if the program&#39;s users have the 4 essential freedoms}:</span></span>
<span class="line"><span>\\begin{itemize}</span></span>
<span class="line"><span>\\item \\vspace{0.2cm} </span></span>
<span class="line"><span>\\noindent \\textbf{The freedom to run} the program as you wish, for any purpose \\textit{(freedom 0)}. \\vspace{0.2cm} </span></span>
<span class="line"><span>\\item \\noindent \\textbf{The freedom to study} how the program works, and change it so it does your computing as you wish \\textit{(freedom 1)}. Access to the source code is a precondition for this.\\vspace{0.2cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\item \\noindent \\textbf{The freedom to redistribute} copies so you can help your neighbour \\textit{(freedom 2)}.\\vspace{0.2cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\item \\noindent \\textbf{The freedom to distribute copies of your modified versions} to others \\textit{(freedom 3)}. \\tiny{By doing this you can give the whole community a chance to benefit from your changes.\\underline{\\textsc{ Access to the source code is a precondition for this.}}}</span></span>
<span class="line"><span>\\end{itemize}</span></span>
<span class="line"><span>\\end{document}</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-18-17-21-30.png" alt=""></p><h3 id="添加列、圖像和鏈接" tabindex="-1">添加列、圖像和鏈接 <a class="header-anchor" href="#添加列、圖像和鏈接" aria-label="Permalink to “添加列、圖像和鏈接”">​</a></h3><p>列、圖像和鏈接有助於為文本添加更多信息。LaTeX 包含一些高級功能的函數作為宏包。<code>\\usepackage</code> 命令加載宏包以便你可以使用這些功能。</p><p>例如，要使用圖像，可以使用命令 <code>\\usepackage{graphicx}</code>。或者，要設置列和鏈接，請分別使用 <code>\\usepackage{multicol}</code> 和 <code>\\usepackage{hyperref}</code>。</p><p><code>\\includegraphics</code> 命令將圖像內聯放置在文檔中。（為簡單起見，請將圖形文件包含在與 LaTeX 源文件相同的目錄中。）</p><p>下面是一個使用所有這些概念的示例。它還使用下載的兩個 PNG 圖片。試試你自己的圖片，看看它們是如何工作的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\documentclass{article} </span></span>
<span class="line"><span>\\usepackage{graphicx}</span></span>
<span class="line"><span>\\usepackage{multicol}</span></span>
<span class="line"><span>\\usepackage{hyperref}</span></span>
<span class="line"><span>\\begin{document} </span></span>
<span class="line"><span> \\textbf{GNU}</span></span>
<span class="line"><span> \\vspace{1cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span> GNU is a recursive acronym for &quot;GNU&#39;s Not Unix!&quot;, chosen because GNU&#39;s design is Unix-like, but differs from Unix by being free software and containing no Unix code.</span></span>
<span class="line"><span></span></span>
<span class="line"><span> Richard Stallman, the founder of the project, views GNU as a &quot;technical means to a social end&quot;. Stallman has written about &quot;the social aspects of software and how Free Software can create community and social justice.&quot; in his &quot;Free Society&quot; book.</span></span>
<span class="line"><span> \\vspace{1cm}</span></span>
<span class="line"><span></span></span>
<span class="line"><span> \\textbf{Some Projects}</span></span>
<span class="line"><span></span></span>
<span class="line"><span> \\begin{multicols}{2}</span></span>
<span class="line"><span> Fedora</span></span>
<span class="line"><span> \\url{https://getfedora.org}</span></span>
<span class="line"><span> \\includegraphics[width=1cm]{fedora.png}</span></span>
<span class="line"><span></span></span>
<span class="line"><span> GNOME</span></span>
<span class="line"><span> \\url{https://getfedora.org}</span></span>
<span class="line"><span> \\includegraphics[width=1cm]{gnome.png}</span></span>
<span class="line"><span> \\end{multicols} </span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\end{document}</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/07/Screenshot-from-2017-10-18-20-32-32.png" alt=""></p>`,28)),a("p",null,[s[4]||(s[4]=e("這裏的功能只觸及 LaTeX 功能的表面。你可以在該項目的",-1)),t(n,{href:"https://www.latex-project.org/help/"},{default:p(()=>[...s[3]||(s[3]=[e("幫助和文檔站點",-1)])]),_:1}),s[5]||(s[5]=e("瞭解更多關於它們的信息。",-1))]),s[24]||(s[24]=a("hr",null,null,-1)),a("p",null,[s[7]||(s[7]=e("via: ",-1)),t(n,{href:"https://fedoramagazine.org/typeset-latex-texstudio-fedora/"},{default:p(()=>[...s[6]||(s[6]=[e("https://fedoramagazine.org/typeset-latex-texstudio-fedora/",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=e("作者：",-1)),t(n,{href:"https://fedoramagazine.org/author/yulytas/"},{default:p(()=>[...s[8]||(s[8]=[e("Julita Inca Chiroque",-1)])]),_:1}),s[13]||(s[13]=e(" 選題：",-1)),t(n,{href:"https://github.com/Chao-zhi"},{default:p(()=>[...s[9]||(s[9]=[e("Chao-zhi",-1)])]),_:1}),s[14]||(s[14]=e(" 譯者：",-1)),t(n,{href:"https://github.com/Chao-zhi"},{default:p(()=>[...s[10]||(s[10]=[e("Chao-zhi",-1)])]),_:1}),s[15]||(s[15]=e(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:p(()=>[...s[17]||(s[17]=[e("Linux中國",-1)])]),_:1}),s[20]||(s[20]=e(" 榮譽推出",-1))])])}const x=o(c,[["render",u]]);export{y as __pageData,x as default};
